pub const USE_EPSILON_TEST: bool = true;
// C's `fabs(du0) < EPSILON` promotes the f32 to double and compares against the
// unsuffixed double literal, so the clamp-to-zero threshold is evaluated in f64.
pub const EPSILON: f64 = 0.000001;

/// Raven `coplanar_tri_tri`.
///
/// Test if two coplanar triangles intersect by projecting onto an axis-aligned
/// plane that maximizes the triangles' area, then testing edge intersections
/// and point-in-triangle tests.
///
/// Source: `oracle/oracle/codemp/game/tri_coll_test.c:149-196`
pub fn coplanar_tri_tri(
    N: vec3_t,
    V0: vec3_t,
    V1: vec3_t,
    V2: vec3_t,
    U0: vec3_t,
    U1: vec3_t,
    U2: vec3_t,
) -> qboolean {
    let mut A = [0.0f32; 3];
    let mut i0: usize;
    let mut i1: usize;

    // First project onto an axis-aligned plane, that maximizes the area
    // of the triangles, compute indices: i0, i1.
    A[0] = N[0].abs();
    A[1] = N[1].abs();
    A[2] = N[2].abs();

    if A[0] > A[1] {
        if A[0] > A[2] {
            i0 = 1; // A[0] is greatest
            i1 = 2;
        } else {
            i0 = 0; // A[2] is greatest
            i1 = 1;
        }
    } else {
        // A[0] <= A[1]
        if A[2] > A[1] {
            i0 = 0; // A[2] is greatest
            i1 = 1;
        } else {
            i0 = 0; // A[1] is greatest
            i1 = 2;
        }
    }

    // Test all edges of triangle 1 against the edges of triangle 2
    // EDGE_AGAINST_TRI_EDGES(V0, V1, U0, U1, U2)
    {
        let Ax = V1[i0] - V0[i0];
        let Ay = V1[i1] - V0[i1];

        // test edge U0,U1 against V0,V1
        {
            let Bx = U0[i0] - U1[i0];
            let By = U0[i1] - U1[i1];
            let Cx = V0[i0] - U0[i0];
            let Cy = V0[i1] - U0[i1];
            let f = Ay * Bx - Ax * By;
            let d = By * Cx - Bx * Cy;
            if (f > 0.0 && d >= 0.0 && d <= f) || (f < 0.0 && d <= 0.0 && d >= f) {
                let e = Ax * Cy - Ay * Cx;
                if f > 0.0 {
                    if e >= 0.0 && e <= f {
                        return 1;
                    }
                } else {
                    if e <= 0.0 && e >= f {
                        return 1;
                    }
                }
            }
        }

        // test edge U1,U2 against V0,V1
        {
            let Bx = U1[i0] - U2[i0];
            let By = U1[i1] - U2[i1];
            let Cx = V0[i0] - U1[i0];
            let Cy = V0[i1] - U1[i1];
            let f = Ay * Bx - Ax * By;
            let d = By * Cx - Bx * Cy;
            if (f > 0.0 && d >= 0.0 && d <= f) || (f < 0.0 && d <= 0.0 && d >= f) {
                let e = Ax * Cy - Ay * Cx;
                if f > 0.0 {
                    if e >= 0.0 && e <= f {
                        return 1;
                    }
                } else {
                    if e <= 0.0 && e >= f {
                        return 1;
                    }
                }
            }
        }

        // test edge U2,U0 against V0,V1
        {
            let Bx = U2[i0] - U0[i0];
            let By = U2[i1] - U0[i1];
            let Cx = V0[i0] - U2[i0];
            let Cy = V0[i1] - U2[i1];
            let f = Ay * Bx - Ax * By;
            let d = By * Cx - Bx * Cy;
            if (f > 0.0 && d >= 0.0 && d <= f) || (f < 0.0 && d <= 0.0 && d >= f) {
                let e = Ax * Cy - Ay * Cx;
                if f > 0.0 {
                    if e >= 0.0 && e <= f {
                        return 1;
                    }
                } else {
                    if e <= 0.0 && e >= f {
                        return 1;
                    }
                }
            }
        }
    }

    // EDGE_AGAINST_TRI_EDGES(V1, V2, U0, U1, U2)
    {
        let Ax = V2[i0] - V1[i0];
        let Ay = V2[i1] - V1[i1];

        // test edge U0,U1 against V1,V2
        {
            let Bx = U0[i0] - U1[i0];
            let By = U0[i1] - U1[i1];
            let Cx = V1[i0] - U0[i0];
            let Cy = V1[i1] - U0[i1];
            let f = Ay * Bx - Ax * By;
            let d = By * Cx - Bx * Cy;
            if (f > 0.0 && d >= 0.0 && d <= f) || (f < 0.0 && d <= 0.0 && d >= f) {
                let e = Ax * Cy - Ay * Cx;
                if f > 0.0 {
                    if e >= 0.0 && e <= f {
                        return 1;
                    }
                } else {
                    if e <= 0.0 && e >= f {
                        return 1;
                    }
                }
            }
        }

        // test edge U1,U2 against V1,V2
        {
            let Bx = U1[i0] - U2[i0];
            let By = U1[i1] - U2[i1];
            let Cx = V1[i0] - U1[i0];
            let Cy = V1[i1] - U1[i1];
            let f = Ay * Bx - Ax * By;
            let d = By * Cx - Bx * Cy;
            if (f > 0.0 && d >= 0.0 && d <= f) || (f < 0.0 && d <= 0.0 && d >= f) {
                let e = Ax * Cy - Ay * Cx;
                if f > 0.0 {
                    if e >= 0.0 && e <= f {
                        return 1;
                    }
                } else {
                    if e <= 0.0 && e >= f {
                        return 1;
                    }
                }
            }
        }

        // test edge U2,U0 against V1,V2
        {
            let Bx = U2[i0] - U0[i0];
            let By = U2[i1] - U0[i1];
            let Cx = V1[i0] - U2[i0];
            let Cy = V1[i1] - U2[i1];
            let f = Ay * Bx - Ax * By;
            let d = By * Cx - Bx * Cy;
            if (f > 0.0 && d >= 0.0 && d <= f) || (f < 0.0 && d <= 0.0 && d >= f) {
                let e = Ax * Cy - Ay * Cx;
                if f > 0.0 {
                    if e >= 0.0 && e <= f {
                        return 1;
                    }
                } else {
                    if e <= 0.0 && e >= f {
                        return 1;
                    }
                }
            }
        }
    }

    // EDGE_AGAINST_TRI_EDGES(V2, V0, U0, U1, U2)
    {
        let Ax = V0[i0] - V2[i0];
        let Ay = V0[i1] - V2[i1];

        // test edge U0,U1 against V2,V0
        {
            let Bx = U0[i0] - U1[i0];
            let By = U0[i1] - U1[i1];
            let Cx = V2[i0] - U0[i0];
            let Cy = V2[i1] - U0[i1];
            let f = Ay * Bx - Ax * By;
            let d = By * Cx - Bx * Cy;
            if (f > 0.0 && d >= 0.0 && d <= f) || (f < 0.0 && d <= 0.0 && d >= f) {
                let e = Ax * Cy - Ay * Cx;
                if f > 0.0 {
                    if e >= 0.0 && e <= f {
                        return 1;
                    }
                } else {
                    if e <= 0.0 && e >= f {
                        return 1;
                    }
                }
            }
        }

        // test edge U1,U2 against V2,V0
        {
            let Bx = U1[i0] - U2[i0];
            let By = U1[i1] - U2[i1];
            let Cx = V2[i0] - U1[i0];
            let Cy = V2[i1] - U1[i1];
            let f = Ay * Bx - Ax * By;
            let d = By * Cx - Bx * Cy;
            if (f > 0.0 && d >= 0.0 && d <= f) || (f < 0.0 && d <= 0.0 && d >= f) {
                let e = Ax * Cy - Ay * Cx;
                if f > 0.0 {
                    if e >= 0.0 && e <= f {
                        return 1;
                    }
                } else {
                    if e <= 0.0 && e >= f {
                        return 1;
                    }
                }
            }
        }

        // test edge U2,U0 against V2,V0
        {
            let Bx = U2[i0] - U0[i0];
            let By = U2[i1] - U0[i1];
            let Cx = V2[i0] - U2[i0];
            let Cy = V2[i1] - U2[i1];
            let f = Ay * Bx - Ax * By;
            let d = By * Cx - Bx * Cy;
            if (f > 0.0 && d >= 0.0 && d <= f) || (f < 0.0 && d <= 0.0 && d >= f) {
                let e = Ax * Cy - Ay * Cx;
                if f > 0.0 {
                    if e >= 0.0 && e <= f {
                        return 1;
                    }
                } else {
                    if e <= 0.0 && e >= f {
                        return 1;
                    }
                }
            }
        }
    }

    // Finally, test if tri1 is totally contained in tri2 or vice versa
    // POINT_IN_TRI(V0, U0, U1, U2)
    {
        let a = U1[i1] - U0[i1];
        let b = -(U1[i0] - U0[i0]);
        let c = -a * U0[i0] - b * U0[i1];
        let d0 = a * V0[i0] + b * V0[i1] + c;

        let a = U2[i1] - U1[i1];
        let b = -(U2[i0] - U1[i0]);
        let c = -a * U1[i0] - b * U1[i1];
        let d1 = a * V0[i0] + b * V0[i1] + c;

        let a = U0[i1] - U2[i1];
        let b = -(U0[i0] - U2[i0]);
        let c = -a * U2[i0] - b * U2[i1];
        let d2 = a * V0[i0] + b * V0[i1] + c;

        if d0 * d1 > 0.0 {
            if d0 * d2 > 0.0 {
                return 1;
            }
        }
    }

    // POINT_IN_TRI(U0, V0, V1, V2)
    {
        let a = V1[i1] - V0[i1];
        let b = -(V1[i0] - V0[i0]);
        let c = -a * V0[i0] - b * V0[i1];
        let d0 = a * U0[i0] + b * U0[i1] + c;

        let a = V2[i1] - V1[i1];
        let b = -(V2[i0] - V1[i0]);
        let c = -a * V1[i0] - b * V1[i1];
        let d1 = a * U0[i0] + b * U0[i1] + c;

        let a = V0[i1] - V2[i1];
        let b = -(V0[i0] - V2[i0]);
        let c = -a * V2[i0] - b * V2[i1];
        let d2 = a * U0[i0] + b * U0[i1] + c;

        if d0 * d1 > 0.0 {
            if d0 * d2 > 0.0 {
                return 1;
            }
        }
    }

    0
}

/// Raven `tri_tri_intersect`.
///
/// Test if two triangles in 3D space intersect. Computes plane equations for
/// both triangles, tests if either triangle pierces the other's plane,
/// then projects onto a 1D interval and checks for overlap.
///
/// Source: `oracle/oracle/codemp/game/tri_coll_test.c:198-292`
pub fn tri_tri_intersect(
    V0: vec3_t,
    V1: vec3_t,
    V2: vec3_t,
    U0: vec3_t,
    U1: vec3_t,
    U2: vec3_t,
) -> qboolean {
    let mut E1 = [0.0f32; 3];
    let mut E2 = [0.0f32; 3];
    let mut N1 = [0.0f32; 3];
    let mut N2 = [0.0f32; 3];
    let mut D = [0.0f32; 3];
    let mut isect1 = [0.0f32; 2];
    let mut isect2 = [0.0f32; 2];

    // Compute plane equation of triangle(V0, V1, V2)
    E1[0] = V1[0] - V0[0];
    E1[1] = V1[1] - V0[1];
    E1[2] = V1[2] - V0[2];

    E2[0] = V2[0] - V0[0];
    E2[1] = V2[1] - V0[1];
    E2[2] = V2[2] - V0[2];

    // CROSS(N1, E1, E2)
    N1[0] = E1[1] * E2[2] - E1[2] * E2[1];
    N1[1] = E1[2] * E2[0] - E1[0] * E2[2];
    N1[2] = E1[0] * E2[1] - E1[1] * E2[0];

    // DOT(N1, V0)
    let d1 = -(N1[0] * V0[0] + N1[1] * V0[1] + N1[2] * V0[2]);
    // Plane equation 1: N1.X+d1=0

    // Put U0, U1, U2 into plane equation 1 to compute signed distances to the plane
    let mut du0 = N1[0] * U0[0] + N1[1] * U0[1] + N1[2] * U0[2] + d1;
    let mut du1 = N1[0] * U1[0] + N1[1] * U1[1] + N1[2] * U1[2] + d1;
    let mut du2 = N1[0] * U2[0] + N1[1] * U2[1] + N1[2] * U2[2] + d1;

    // Coplanarity robustness check
    if USE_EPSILON_TEST {
        if (du0 as f64).abs() < EPSILON {
            du0 = 0.0;
        }
        if (du1 as f64).abs() < EPSILON {
            du1 = 0.0;
        }
        if (du2 as f64).abs() < EPSILON {
            du2 = 0.0;
        }
    }

    let du0du1 = du0 * du1;
    let du0du2 = du0 * du2;

    if du0du1 > 0.0 && du0du2 > 0.0 {
        // Same sign on all of them + not equal 0?
        return 0; // No intersection occurs
    }

    // Compute plane of triangle (U0, U1, U2)
    E1[0] = U1[0] - U0[0];
    E1[1] = U1[1] - U0[1];
    E1[2] = U1[2] - U0[2];

    E2[0] = U2[0] - U0[0];
    E2[1] = U2[1] - U0[1];
    E2[2] = U2[2] - U0[2];

    // CROSS(N2, E1, E2)
    N2[0] = E1[1] * E2[2] - E1[2] * E2[1];
    N2[1] = E1[2] * E2[0] - E1[0] * E2[2];
    N2[2] = E1[0] * E2[1] - E1[1] * E2[0];

    // DOT(N2, U0)
    let d2 = -(N2[0] * U0[0] + N2[1] * U0[1] + N2[2] * U0[2]);
    // Plane equation 2: N2.X+d2=0

    // Put V0, V1, V2 into plane equation 2
    let mut dv0 = N2[0] * V0[0] + N2[1] * V0[1] + N2[2] * V0[2] + d2;
    let mut dv1 = N2[0] * V1[0] + N2[1] * V1[1] + N2[2] * V1[2] + d2;
    let mut dv2 = N2[0] * V2[0] + N2[1] * V2[1] + N2[2] * V2[2] + d2;

    if USE_EPSILON_TEST {
        if (dv0 as f64).abs() < EPSILON {
            dv0 = 0.0;
        }
        if (dv1 as f64).abs() < EPSILON {
            dv1 = 0.0;
        }
        if (dv2 as f64).abs() < EPSILON {
            dv2 = 0.0;
        }
    }

    let dv0dv1 = dv0 * dv1;
    let dv0dv2 = dv0 * dv2;

    if dv0dv1 > 0.0 && dv0dv2 > 0.0 {
        // Same sign on all of them + not equal 0?
        return 0; // No intersection occurs
    }

    // Compute direction of intersection line
    D[0] = N1[1] * N2[2] - N1[2] * N2[1];
    D[1] = N1[2] * N2[0] - N1[0] * N2[2];
    D[2] = N1[0] * N2[1] - N1[1] * N2[0];

    // Compute and index to the largest component of D
    let mut max = D[0].abs();
    let mut index = 0;
    let b = D[1].abs();
    let c = D[2].abs();
    if b > max {
        max = b;
        index = 1;
    }
    if c > max {
        max = c;
        index = 2;
    }

    // This is the simplified projection onto L
    let vp0 = V0[index];
    let vp1 = V1[index];
    let vp2 = V2[index];

    let up0 = U0[index];
    let up1 = U1[index];
    let up2 = U2[index];

    // Compute interval for triangle 1
    // COMPUTE_INTERVALS(vp0, vp1, vp2, dv0, dv1, dv2, dv0dv1, dv0dv2, isect1[0], isect1[1])
    {
        if dv0dv1 > 0.0 {
            // Here we know that dv0dv2 <= 0.0
            // That is dv0, dv1 are on the same side, dv2 on the other or on the plane
            // ISECT(vp2, vp0, vp1, dv2, dv0, dv1, isect1[0], isect1[1])
            isect1[0] = vp2 + (vp0 - vp2) * dv2 / (dv2 - dv0);
            isect1[1] = vp2 + (vp1 - vp2) * dv2 / (dv2 - dv1);
        } else if dv0dv2 > 0.0 {
            // Here we know that dv0dv1 <= 0.0
            // ISECT(vp1, vp0, vp2, dv1, dv0, dv2, isect1[0], isect1[1])
            isect1[0] = vp1 + (vp0 - vp1) * dv1 / (dv1 - dv0);
            isect1[1] = vp1 + (vp2 - vp1) * dv1 / (dv1 - dv2);
        } else if dv1 * dv2 > 0.0 || dv0 != 0.0 {
            // Here we know that dv0dv1 <= 0.0 or that dv0 != 0.0
            // ISECT(vp0, vp1, vp2, dv0, dv1, dv2, isect1[0], isect1[1])
            isect1[0] = vp0 + (vp1 - vp0) * dv0 / (dv0 - dv1);
            isect1[1] = vp0 + (vp2 - vp0) * dv0 / (dv0 - dv2);
        } else if dv1 != 0.0 {
            // ISECT(vp1, vp0, vp2, dv1, dv0, dv2, isect1[0], isect1[1])
            isect1[0] = vp1 + (vp0 - vp1) * dv1 / (dv1 - dv0);
            isect1[1] = vp1 + (vp2 - vp1) * dv1 / (dv1 - dv2);
        } else if dv2 != 0.0 {
            // ISECT(vp2, vp0, vp1, dv2, dv0, dv1, isect1[0], isect1[1])
            isect1[0] = vp2 + (vp0 - vp2) * dv2 / (dv2 - dv0);
            isect1[1] = vp2 + (vp1 - vp2) * dv2 / (dv2 - dv1);
        } else {
            // Triangles are coplanar
            return coplanar_tri_tri(N1, V0, V1, V2, U0, U1, U2);
        }
    }

    // Compute interval for triangle 2
    // COMPUTE_INTERVALS(up0, up1, up2, du0, du1, du2, du0du1, du0du2, isect2[0], isect2[1])
    {
        if du0du1 > 0.0 {
            // Here we know that du0du2 <= 0.0
            // ISECT(up2, up0, up1, du2, du0, du1, isect2[0], isect2[1])
            isect2[0] = up2 + (up0 - up2) * du2 / (du2 - du0);
            isect2[1] = up2 + (up1 - up2) * du2 / (du2 - du1);
        } else if du0du2 > 0.0 {
            // Here we know that du0du1 <= 0.0
            // ISECT(up1, up0, up2, du1, du0, du2, isect2[0], isect2[1])
            isect2[0] = up1 + (up0 - up1) * du1 / (du1 - du0);
            isect2[1] = up1 + (up2 - up1) * du1 / (du1 - du2);
        } else if du1 * du2 > 0.0 || du0 != 0.0 {
            // Here we know that du0du1 <= 0.0 or that du0 != 0.0
            // ISECT(up0, up1, up2, du0, du1, du2, isect2[0], isect2[1])
            isect2[0] = up0 + (up1 - up0) * du0 / (du0 - du1);
            isect2[1] = up0 + (up2 - up0) * du0 / (du0 - du2);
        } else if du1 != 0.0 {
            // ISECT(up1, up0, up2, du1, du0, du2, isect2[0], isect2[1])
            isect2[0] = up1 + (up0 - up1) * du1 / (du1 - du0);
            isect2[1] = up1 + (up2 - up1) * du1 / (du1 - du2);
        } else if du2 != 0.0 {
            // ISECT(up2, up0, up1, du2, du0, du1, isect2[0], isect2[1])
            isect2[0] = up2 + (up0 - up2) * du2 / (du2 - du0);
            isect2[1] = up2 + (up1 - up2) * du2 / (du2 - du1);
        } else {
            // Triangles are coplanar. The COMPUTE_INTERVALS macro hardcodes N1 in
            // both expansions, so this branch passes N1, not N2.
            return coplanar_tri_tri(N1, V0, V1, V2, U0, U1, U2);
        }
    }

    // SORT(isect1[0], isect1[1])
    if isect1[0] > isect1[1] {
        let tmp = isect1[0];
        isect1[0] = isect1[1];
        isect1[1] = tmp;
    }

    // SORT(isect2[0], isect2[1])
    if isect2[0] > isect2[1] {
        let tmp = isect2[0];
        isect2[0] = isect2[1];
        isect2[1] = tmp;
    }

    if isect1[1] < isect2[0] || isect2[1] < isect1[0] {
        return 1;
    }
    0
}
